func:
// Price Planner
// v2.15 - bug fixes from simulation review —
//          (1) crash (whole flow stops, EMS never runs) when the price array has
//              no remaining hours for today; now falls back like "no prices"
//          (2) MAX_AMPS 200 → 100 to match the EMS (100A since EMS v3.42); the
//              charge window was sized for 8.16 kW while the battery charges at
//              ~4.1 kW → only half the hours needed; MAX_DISCHARGE_KW is now
//              derived from MAX_AMPS (4.8 kW, was hardcoded 9.6)
//          (3) charge window never expands into above-average hours
//          (4) solar-before-cheap-window capped by the remaining forecast — the
//              current rate × hours ran past sunset and falsely flagged overfill
//          (5) no overfill flag without solar (0 >= 0 triggered it when full)
//          (6) solar pre-discharge frees at least 3 kWh when possible — it was
//              capped by headroom, so a near-full battery freed almost nothing
//          (7) hour/date taken from the parsed timestamp, not the string —
//              correct for both local-offset and UTC ('Z') timestamps
// v2.14 - solar overfill pre-discharge: if solar forecast will fill the battery
//          before the cheap window opens, discharge now to make room for cheap grid charging
// v2.13 - discharge window centered on most expensive hour and expanded outward;
//          window size based on actual kWh available to discharge at max rate
// v2.12 - charge window only built when cheapestPrice <= chargePriceCap;
//          prevents building a window around expensive hours at night
// v2.11 - pre-discharge before upcoming negative price windows;
//          if negative prices are forecast ahead, discharge now to free capacity
// v2.10 - count remaining negative price hours and pass to EMS so negative
//          price charging is spread across the full negative window instead of max rate
// v2.9 - charge window expansion biased toward earlier hours when neighbour prices
//         are within EARLY_BIAS_EUR of each other; keeps grid charging before solar peak
// v2.8 - solar forecast (energy_production_remaining_today) deducted from kwhNeeded;
//         grid charge window shrinks when solar will cover part of the charge
// v2.7 - discharge band filter raised to avgPrice (hours below avg can never be discharge hours)
// v2.6 - charge window centered on cheapest hour, expanded outward; price cap
//         replaced by contiguous window logic — lowest price sits in center of charge period
// v2.5 - dynamic CHARGE_ABS_RATIO/DISCHARGE_ABS_RATIO aligned with EMS v3.4
// v2.4 - avgPrice and currentPrice calculated from Frank Energie array, EnergyZero removed
// v2.3 - version defined as single variable at top
// v2.2 - SOC_NORMAL_THRESHOLD raised to 80%
// v2.1 - fixed msg.plannerVersion, DISCHARGE_ABS_MIN corrected
// v2.0 - dischargeThreshold recalculated after conflict filter

var PLANNER_VERSION      = 'v2.15';
var BATTERY_KWH          = 40;
var BATTERY_VOLTAGE      = 48;
var MAX_AMPS             = 100;   // v2.15: was 200 — must match EMS CFG.MAX_AMPS
var ROUND_TRIP_EFF       = 0.85;
var SOC_MIN              = 10;
var SOC_MAX              = 95;
var SAFETY_BUFFER_H      = 1;
var SOC_NORMAL_THRESHOLD = 80;    // above this, use tight charge cap
var CHARGE_ABS_RATIO     = 0.55;  // tight cap = avg * this (mirrors EMS v3.4)
var DISCHARGE_ABS_RATIO  = 0.55;  // min discharge price = avg * this (mirrors EMS v3.4)
var SOLAR_FORECAST_EFF   = 0.90;  // how much of the solar forecast actually reaches the battery
var EARLY_BIAS_EUR       = 0.02;  // prefer earlier hour when price difference is within this margin
var LATE_BIAS_EUR        = 0.02;  // prefer later hour when discharge neighbour prices are within this margin
var MAX_DISCHARGE_KW     = MAX_AMPS * BATTERY_VOLTAGE / 1000;   // v2.15: derived (4.8 kW), was hardcoded 9.6
var SOLAR_OVERFILL_RATIO = 1.0;   // solar usable / headroom ratio above which overfill is expected
var SOLAR_PRE_MIN_HOURS  = 1;     // minimum hours before cheap window needed for pre-discharge
// Note: solarNow_W requires msg.solarNow to be set in the Node-RED chain
// Add a function node before Price Planner: msg.solarNow = msg.pac1 + msg.pac2 + msg.pac3
var SOC_DISCHARGE_MAX    = 95;    // SoC from which discharge starts
var SOC_DISCHARGE_MIN_PL = 15;    // SoC floor for discharge

var maxChargeKw = (MAX_AMPS * BATTERY_VOLTAGE / 1000) * ROUND_TRIP_EFF;

var batterySoC  = parseFloat(msg.batterySoC) || parseFloat(context.get('lastSoC')) || 50;
context.set('lastSoC', batterySoC);
var solarNow_W  = parseFloat(msg.solarNow) || 0;  // current solar production in W (from EMS chain)

// Solar forecast — kWh still expected today from Forecast.Solar integration
// Entity: sensor.energy_production_remaining_today (kWh)
// Falls back to 0 if sensor is unavailable so planner remains conservative
var solarForecastKwh = parseFloat(msg.solarForecastRemaining) || 0;
var solarUsableKwh   = solarForecastKwh * SOLAR_FORECAST_EFF;  // apply efficiency loss

var usableCapacity = BATTERY_KWH * ((SOC_MAX - SOC_MIN) / 100);
var currentKwh     = BATTERY_KWH * ((batterySoC - SOC_MIN) / 100);
var kwhNeeded      = Math.max(0, usableCapacity - currentKwh);

// For grid charge planning, only deduct solar that arrives AFTER the cheap window.
// Solar arriving before the cheap window fills the battery independently — it
// cannot be relied upon to leave room for cheap grid charging.
// We estimate solar timing linearly: cheapWindowStartOffset / totalRemainingHours × total.
// At this point we don't know the cheap window yet, so use a two-pass approach:
// First pass uses total solar for a rough hoursNeeded, second pass (after window is known)
// recalculates with solar-after-window. For now use total solar as conservative estimate.
var kwhFromGrid    = Math.max(0, kwhNeeded - solarUsableKwh);  // solar covers part; grid covers rest
var hoursNeeded    = Math.ceil(kwhFromGrid / maxChargeKw) + SAFETY_BUFFER_H;

// Accept Frank Energie price array in either format
var prices = null;
if (Array.isArray(msg.frankPrices)) {
  prices = msg.frankPrices;
} else if (msg.frankPrices && Array.isArray(msg.frankPrices.prices)) {
  prices = msg.frankPrices.prices;
}

var setFallback = function(reason) {
  msg.plannerVersion             = PLANNER_VERSION;
  msg.inChargingWindow           = null;
  msg.inDischargeWindow          = null;
  msg.dischargeThreshold         = null;
  msg.plannedChargeHours         = [];
  msg.plannedDischargeHours      = [];
  msg.hoursNeeded                = hoursNeeded;
  msg.kwhNeeded                  = parseFloat(kwhNeeded.toFixed(2));
  msg.kwhFromGrid                = parseFloat(kwhFromGrid.toFixed(2));
  msg.solarForecastKwh           = parseFloat(solarUsableKwh.toFixed(2));
  msg.cheapestPrice              = null;
  msg.cheapestHour               = null;
  msg.negPriceHoursRemaining     = 0;
  msg.inPreDischargeWindow       = false;
  msg.preDischargeHours          = [];
  msg.hoursUntilNegWindow        = null;
  msg.futureNegHoursCount        = 0;
  msg.inSolarPreDischargeWindow  = false;
  msg.solarPreDischargeHours     = [];
  msg.solarPreDischargeTargetSoC = SOC_DISCHARGE_MIN_PL;
  msg.kwhToFreeForSolar          = 0;
  msg.solarWillOverfill          = false;
  msg.solarAfterCheapWindow      = 0;
  msg.kwhNeededForGrid           = parseFloat(kwhFromGrid.toFixed(2));
  msg.plannerReason              = reason + ' - using ratio fallback';
  node.status({ fill: 'yellow', shape: 'dot', text: PLANNER_VERSION + ' ' + reason + ' - fallback mode' });
};

if (!prices || prices.length === 0) {
  setFallback('No price schedule available');
  return msg;
}

var now         = new Date();
var currentHour = now.getHours();

// Determine local date string for today's prices
var localOffset  = now.getTimezoneOffset() * 60000;
var localNow     = new Date(now.getTime() - localOffset);
var localDateStr = localNow.toISOString().substring(0, 10);

// Parse all prices and calculate avg + current from the array directly
var allParsed    = [];
var totalPrice   = 0;
var todayCount   = 0;
var currentPriceCalc = null;

for (var i = 0; i < prices.length; i++) {
  var p        = prices[i];
  var fromDate = new Date(p.from);
  var tillDate = new Date(p.till);
  // v2.15: derive local hour/date from the parsed timestamp, not the string —
  // correct whether Frank returns local-offset or UTC ('Z') timestamps
  var localHour = fromDate.getHours();
  var dateStr   = fromDate.getFullYear() + '-' + String(fromDate.getMonth() + 1).padStart(2, '0')
                + '-' + String(fromDate.getDate()).padStart(2, '0');
  allParsed.push({ from: fromDate, till: tillDate, price: parseFloat(p.price), localHour: localHour, dateStr: dateStr });

  if (dateStr === localDateStr) {
    totalPrice += parseFloat(p.price);
    todayCount++;
    if (localHour === currentHour) {
      currentPriceCalc = parseFloat(p.price);
    }
  }
}

var avgPriceCalc = todayCount > 0 ? totalPrice / todayCount : 0.10;

// Override msg so EMS uses Frank Energie prices
msg.currentPrice = currentPriceCalc !== null ? String(currentPriceCalc) : msg.currentPrice;
msg.avgPrice     = String(avgPriceCalc);

// Dynamic price caps based on today's average (mirrors EMS CFG ratios)
var chargePriceCap  = batterySoC >= SOC_NORMAL_THRESHOLD
  ? avgPriceCalc * CHARGE_ABS_RATIO      // tight: SoC healthy
  : avgPriceCalc * 0.99;                 // expanded: SoC low — any below-avg hour qualifies
var dischargeAbsMin = avgPriceCalc * DISCHARGE_ABS_RATIO;

// Only consider remaining hours today
var remainingToday = [];
for (var r = 0; r < allParsed.length; r++) {
  if (allParsed[r].dateStr === localDateStr && allParsed[r].till > now) {
    remainingToday.push(allParsed[r]);
  }
}

// v2.15: no remaining hours for today (array holds only tomorrow, or stale data)
// → fall back instead of crashing on remainingToday[0] below
if (remainingToday.length === 0) {
  setFallback('No remaining price hours for today');
  return msg;
}

// Count remaining hours with negative price — used by EMS to spread charge rate
var negPriceHoursRemaining = 0;
for (var np = 0; np < remainingToday.length; np++) {
  if (remainingToday[np].price < 0) negPriceHoursRemaining++;
}

// Detect upcoming negative price hours for pre-discharge strategy.
// If negative prices are coming later today, we want to discharge the battery
// now (at the best current price) to free up capacity for negative price charging.
var now2 = new Date();
var currentHourVal = now2.getHours();
var futureNegHours = [];         // negative price hours still in the future (not current hour)
var firstNegHourIdx = -1;        // index in remainingToday of first future negative hour

for (var fn = 0; fn < remainingToday.length; fn++) {
  if (remainingToday[fn].price < 0 && remainingToday[fn].localHour > currentHourVal) {
    futureNegHours.push(remainingToday[fn]);
    if (firstNegHourIdx === -1) firstNegHourIdx = fn;
  }
}

var hoursUntilNegWindow = firstNegHourIdx !== -1
  ? remainingToday[firstNegHourIdx].localHour - currentHourVal
  : 99;

// How much capacity can we free by discharging to SOC_DISCHARGE_MIN?
var SOC_DISCHARGE_MIN_LOCAL = SOC_DISCHARGE_MIN_PL;
var currentKwhForDischarge  = BATTERY_KWH * ((batterySoC - SOC_MIN) / 100);
var minKwh                  = BATTERY_KWH * ((SOC_DISCHARGE_MIN_LOCAL - SOC_MIN) / 100);
var capacityToFree          = Math.max(0, currentKwhForDischarge - minKwh);

// Pre-discharge window: hours between now and the negative window where price > dischargeAbsMin
// We only pre-discharge in hours that are worth discharging (above avg × DISCHARGE_ABS_RATIO)
var preDischargeHours = [];
if (futureNegHours.length > 0 && hoursUntilNegWindow > 0 && hoursUntilNegWindow < 99) {
  for (var pd = 0; pd < remainingToday.length; pd++) {
    var pdHour = remainingToday[pd];
    // Only hours before the negative window, above dischargeAbsMin, and not already negative
    if (pdHour.localHour < futureNegHours[0].localHour
        && pdHour.price >= avgPriceCalc * DISCHARGE_ABS_RATIO
        && pdHour.price >= 0) {
      preDischargeHours.push(pdHour.localHour);
    }
  }
}

var inPreDischargeWindow = preDischargeHours.indexOf(currentHourVal) !== -1
  && futureNegHours.length > 0
  && batterySoC > SOC_DISCHARGE_MIN_LOCAL
  && capacityToFree > 0;

// Solar overfill pre-discharge:
// If current solar production will fill the battery before the cheap price window opens,
// discharge now to create headroom so the cheap grid window can actually be used.
//
// Uses current real-time solar production rate (W) × hours until cheap window
// to estimate how much solar will arrive before the window — more accurate than
// the daily forecast total which doesn't account for timing.
//
// Also always reserves MIN_GRID_CHEAP_KWH headroom at the cheapest hour regardless,
// so the system always buys some energy at the lowest price of the day.
var MIN_GRID_CHEAP_KWH = 3.0;  // minimum kWh to always absorb at cheapest price

// First pass: find cheapest hour from remaining today for overfill check
var planPricesCheck    = remainingToday.slice();
planPricesCheck.sort(function(a, b) { return a.price - b.price; });
var cheapestHourCheck  = planPricesCheck.length > 0 ? planPricesCheck[0].localHour : 99;
var cheapestPriceCheck = planPricesCheck.length > 0 ? planPricesCheck[0].price : 999;
var cheapWindowAhead   = cheapestPriceCheck <= chargePriceCap;
var windowNotYetOpen   = cheapestHourCheck > currentHourVal;

var hoursUntilCheapWindowLocal = Math.max(0, cheapestHourCheck - currentHourVal);
var totalRemainingHours        = Math.max(1, remainingToday.length);

// Estimate solar arriving before cheap window using current production rate
var solarRateKwh          = solarNow_W / 1000;  // current kW
var solarBeforeCheapWindow = Math.min(solarRateKwh * hoursUntilCheapWindowLocal, solarUsableKwh);  // v2.15: capped by forecast — the current rate doesn't last past sunset

// Recalculate kwhFromGrid using only solar AFTER cheap window
var solarAfterCheapWindow = Math.max(0, solarUsableKwh - solarBeforeCheapWindow);
kwhFromGrid  = Math.max(0, kwhNeeded - solarAfterCheapWindow);
hoursNeeded  = Math.ceil(kwhFromGrid / maxChargeKw) + SAFETY_BUFFER_H;

var currentHeadroom = Math.max(0, usableCapacity - currentKwh);

// Solar will overfill if estimated solar before window exceeds available headroom
var solarWillOverfill = cheapWindowAhead
  && solarBeforeCheapWindow > 0     // v2.15: no solar → no overfill
  && windowNotYetOpen
  && solarBeforeCheapWindow >= currentHeadroom * SOLAR_OVERFILL_RATIO
  && hoursUntilCheapWindowLocal > 0;

// kWh to free = max of what grid window needs AND minimum cheap-hour absorption
// Even if kwhFromGrid=0 (solar covers all), we still want to buy MIN_GRID_CHEAP_KWH
// at the cheapest price of the day
var kwhToFreeForSolar  = 0;
var solarPreDischargeHours = [];
var inSolarPreDischargeWindow = false;
var solarPreDischargeTargetSoC = SOC_DISCHARGE_MIN_PL;

if (solarWillOverfill) {
  // v2.15: bounded by energy that can actually be discharged, not by headroom —
  // a near-full battery (the typical overfill case) freed almost nothing before
  kwhToFreeForSolar = Math.min(
    Math.max(kwhFromGrid, MIN_GRID_CHEAP_KWH),
    capacityToFree
  );

  var kwhAfterDischarge = Math.max(
    BATTERY_KWH * ((SOC_DISCHARGE_MIN_PL - SOC_MIN) / 100),
    currentKwh - kwhToFreeForSolar
  );
  solarPreDischargeTargetSoC = Math.round(SOC_MIN + (kwhAfterDischarge / BATTERY_KWH * 100));

  // Pre-discharge hours: from now until cheap window, price above dischargeAbsMin
  for (var sp = 0; sp < remainingToday.length; sp++) {
    var spHour = remainingToday[sp];
    if (spHour.localHour < cheapestHourCheck
        && spHour.localHour >= currentHourVal
        && spHour.price >= dischargeAbsMin
        && spHour.price >= 0) {
      solarPreDischargeHours.push(spHour.localHour);
    }
  }

  inSolarPreDischargeWindow = solarPreDischargeHours.indexOf(currentHourVal) !== -1
    && batterySoC > solarPreDischargeTargetSoC
    && solarPreDischargeHours.length >= SOLAR_PRE_MIN_HOURS;
}

// Sort remaining by price ascending to find cheapest hour
var planPrices = remainingToday.slice();
planPrices.sort(function(a, b) { return a.price - b.price; });

var cheapestPrice = planPrices.length > 0 ? planPrices[0].price : null;

// Build charge window centered on the cheapest hour, expanding outward.
// remainingToday is already in time order (ascending from). Find the index
// of the cheapest hour within it, then expand left/right picking the
// cheaper neighbour at each step until hoursNeeded slots are filled.
// This guarantees the cheapest hour is always inside the window and the
// window is contiguous in time — the battery charges through the price valley.

var cheapestHour = planPrices.length > 0 ? planPrices[0].localHour : currentHour;

// Find center index in time-ordered remainingToday
var centerIdx = 0;
for (var ci = 0; ci < remainingToday.length; ci++) {
  if (remainingToday[ci].localHour === cheapestHour) { centerIdx = ci; break; }
}

var windowIndices = [centerIdx];
var left  = centerIdx - 1;
var right = centerIdx + 1;

while (windowIndices.length < hoursNeeded) {
  // v2.15: never extend the charge window into above-average hours
  var canLeft  = left >= 0                    && remainingToday[left].price  < avgPriceCalc;
  var canRight = right < remainingToday.length && remainingToday[right].price < avgPriceCalc;
  if (!canLeft && !canRight) break;

  var pickLeft;
  if      (!canRight) { pickLeft = true; }
  else if (!canLeft)  { pickLeft = false; }
  else {
    var leftPrice  = remainingToday[left].price;
    var rightPrice = remainingToday[right].price;
    var priceDiff  = rightPrice - leftPrice;  // positive = right is more expensive
    if (priceDiff >= -EARLY_BIAS_EUR) {
      // Right is more expensive, same price, or only marginally cheaper than left:
      // prefer left (earlier hour) — keeps grid charging before solar peak.
      // Only pick right when it is cheaper by more than the bias margin.
      pickLeft = true;
    } else {
      pickLeft = false;
    }
  }

  if (pickLeft) { windowIndices.push(left);  left--;  }
  else          { windowIndices.push(right); right++; }
}

var cheapestHours = [];
for (var wi = 0; wi < windowIndices.length; wi++) {
  cheapestHours.push(remainingToday[windowIndices[wi]].localHour);
}

// Only build a charge window if the cheapest available hour is actually below
// the price cap. If all remaining hours are expensive (e.g. late evening),
// no charge window is set — the EMS falls back to ratio-based logic only.
var chargeWindowValid = cheapestPrice !== null && cheapestPrice <= chargePriceCap;
if (!chargeWindowValid) {
  cheapestHours = [];
}
var inWindow = chargeWindowValid && cheapestHours.indexOf(currentHour) !== -1;

// Calculate discharge window size from actual kWh available
var kwhToDischarge       = BATTERY_KWH * ((SOC_DISCHARGE_MAX - SOC_DISCHARGE_MIN_PL) / 100);
var dischargeHoursNeeded = Math.min(Math.ceil(kwhToDischarge / MAX_DISCHARGE_KW) + 1, remainingToday.length);

// Find most expensive remaining hour (above avgPrice) as window center
var dischargePool = [];
for (var dp = 0; dp < remainingToday.length; dp++) {
  if (remainingToday[dp].price >= avgPriceCalc) {
    dischargePool.push(remainingToday[dp]);
  }
}
dischargePool.sort(function(a, b) { return b.price - a.price; });

var expensiveHours     = [];
var dischargeThreshold = null;

if (dischargePool.length > 0) {
  var mostExpensiveHour = dischargePool[0].localHour;

  var dCenterIdx = 0;
  for (var dc = 0; dc < remainingToday.length; dc++) {
    if (remainingToday[dc].localHour === mostExpensiveHour) { dCenterIdx = dc; break; }
  }

  // Expand outward from most expensive hour.
  // LATE_BIAS_EUR: when neighbours are within margin, prefer the later hour
  // to keep the window anchored in the evening peak band.
  var dWindowIdx = [dCenterIdx];
  var dLeft  = dCenterIdx - 1;
  var dRight = dCenterIdx + 1;

  while (dWindowIdx.length < dischargeHoursNeeded) {
    var dCanLeft  = dLeft  >= 0                    && remainingToday[dLeft].price  >= avgPriceCalc;
    var dCanRight = dRight < remainingToday.length && remainingToday[dRight].price >= avgPriceCalc;
    if (!dCanLeft && !dCanRight) break;

    var dPickLeft;
    if      (!dCanRight) { dPickLeft = true; }
    else if (!dCanLeft)  { dPickLeft = false; }
    else {
      var dDiff = remainingToday[dLeft].price - remainingToday[dRight].price;
      dPickLeft = dDiff > LATE_BIAS_EUR;  // only pick left if meaningfully more expensive
    }

    if (dPickLeft) { dWindowIdx.push(dLeft);  dLeft--;  }
    else           { dWindowIdx.push(dRight); dRight++; }
  }

  for (var dw = 0; dw < dWindowIdx.length; dw++) {
    expensiveHours.push(remainingToday[dWindowIdx[dw]].localHour);
  }

  // Remove hours conflicting with charge window
  var filteredDischargeHours = [];
  for (var fd = 0; fd < expensiveHours.length; fd++) {
    if (cheapestHours.indexOf(expensiveHours[fd]) === -1) {
      filteredDischargeHours.push(expensiveHours[fd]);
    }
  }
  expensiveHours = filteredDischargeHours;

  // Threshold = lowest price in selected discharge window
  for (var rt = 0; rt < remainingToday.length; rt++) {
    if (expensiveHours.indexOf(remainingToday[rt].localHour) !== -1) {
      if (dischargeThreshold === null || remainingToday[rt].price < dischargeThreshold) {
        dischargeThreshold = remainingToday[rt].price;
      }
    }
  }
}

cheapestHours.sort(function(a, b) { return a - b; });
expensiveHours.sort(function(a, b) { return a - b; });

var inDischargeWindow = expensiveHours.indexOf(currentHour) !== -1;

msg.plannerVersion        = PLANNER_VERSION;
msg.inChargingWindow      = inWindow;
msg.inDischargeWindow     = inDischargeWindow;
msg.dischargeThreshold    = dischargeThreshold;
msg.plannedChargeHours    = cheapestHours;
msg.plannedDischargeHours = expensiveHours;
msg.hoursNeeded           = hoursNeeded;
msg.kwhNeeded             = parseFloat(kwhNeeded.toFixed(2));
msg.cheapestPrice              = cheapestPrice;
msg.cheapestHour               = (typeof cheapestHour !== 'undefined') ? cheapestHour : null;
  msg.negPriceHoursRemaining     = negPriceHoursRemaining;
  msg.inPreDischargeWindow       = inPreDischargeWindow;
  msg.preDischargeHours          = preDischargeHours;
  msg.hoursUntilNegWindow        = hoursUntilNegWindow < 99 ? hoursUntilNegWindow : null;
  msg.futureNegHoursCount             = futureNegHours.length;
  msg.inSolarPreDischargeWindow       = inSolarPreDischargeWindow;
  msg.solarPreDischargeHours          = solarPreDischargeHours;
  msg.solarPreDischargeTargetSoC      = solarPreDischargeTargetSoC;
  msg.kwhToFreeForSolar               = parseFloat(kwhToFreeForSolar.toFixed(2));
  msg.solarWillOverfill               = solarWillOverfill;
  msg.solarAfterCheapWindow           = parseFloat(solarAfterCheapWindow.toFixed(2));
  msg.kwhNeededForGrid                = parseFloat(kwhFromGrid.toFixed(2));
msg.plannerReason         =
  'Need ' + kwhNeeded.toFixed(1) + ' kWh total' +
    (solarUsableKwh > 0 ? ', solar covers ~' + solarUsableKwh.toFixed(1) + ' kWh, ' + kwhFromGrid.toFixed(1) + ' kWh from grid (' + hoursNeeded + 'h)' : ' from grid (' + hoursNeeded + 'h)') + '. ' +
  'SoC ' + batterySoC + '% - cheapest hour: ' + cheapestHour + 'h (' + (cheapestPrice !== null ? cheapestPrice.toFixed(3) : '?') + ' EUR), window centered there. ' +
  'Avg: ' + avgPriceCalc.toFixed(3) + ' EUR. ' +
  'Charge hours: ' + cheapestHours.map(function(h) { return h + 'h'; }).join(', ') +
  '. Discharge hours: ' + expensiveHours.map(function(h) { return h + 'h'; }).join(', ') +
  '. Discharge threshold: ' + (dischargeThreshold ? dischargeThreshold.toFixed(3) : '?') + ' EUR' +
  '. In charge window: ' + inWindow +
  '. In discharge window: ' + inDischargeWindow +
  (futureNegHours.length > 0 ? '. Neg price in ' + (hoursUntilNegWindow < 99 ? hoursUntilNegWindow + 'h' : '?') + ' (' + futureNegHours.length + ' neg hour(s)). Pre-discharge: ' + inPreDischargeWindow : '') +
  (solarWillOverfill ? '. Solar overfill expected — pre-discharge to ' + solarPreDischargeTargetSoC + '% (' + kwhToFreeForSolar.toFixed(1) + ' kWh). Solar pre-dch: ' + inSolarPreDischargeWindow : '') +
  '. Solar after window: ' + solarAfterCheapWindow.toFixed(1) + ' kWh';

node.status({
  fill:  inWindow ? 'green' : inDischargeWindow ? 'red' : 'grey',
  shape: 'dot',
  text:  PLANNER_VERSION + ' ' + (inWindow ? 'CHG' : inDischargeWindow ? 'DCH' : 'IDLE') +
    ' | SoC:' + batterySoC + '% cap:' + chargePriceCap.toFixed(2) +
    ' | dch>' + (dischargeThreshold ? dischargeThreshold.toFixed(3) : '?') + 'EUR' +
    ' | hour ' + currentHour + 'h'
});

return msg;

// EMS Decision Engine
// v3.93 - EV v2.22: charger decides, car data is optional — fixes a deadlock
//          introduced in v3.90: with ev_soc unavailable (guest car, or the
//          car integration offline) and Zaptec in connected_finished, the car
//          was treated as full and got 0A all night; at 0A it could never start,
//          so Zaptec stayed in connected_finished. Now:
//          - car data never forces 0A; a connected car always gets the normal
//            target (a full car simply draws nothing)
//          - "car full" only when ev_soc is known and >= 100%; it only stops the
//            finished-early nudges
//          - unknown SoC → treated as "may need charge": normal rules + nudges
//          - low-SoC priority still needs a known SoC (guest cars: normal rules)
// v3.92 - EV v2.21: EV low-SoC priority — when the car's SoC is below 55% the
//          EV charges at up to 12A 3-phase day and night (1A per ~15 min ramp),
//          regardless of price and battery state; switches off again at 60%.
//          All load rules still apply: 20A phase headroom, confirmed-overload
//          trim / soft cut / session cut, the 15-min hold and the 17–19h
//          blackout. Moves up from single-phase to 3-phase only with at least
//          8A headroom on every phase.
// v3.91 - EV v2.20: more stable night charging (3x25A fuse) —
//          (1) overload must be confirmed: any phase > 22A reacts at once,
//              20–22A only after two consecutive readings (single marginal
//              spikes like 20.02A are ignored)
//          (2) on 3 phases the EV is first trimmed by the excess and stays on
//              3 phases — an amp change does not restart the Zaptec session;
//              only if that would go below 7A does it switch to single-phase
//          (3) after any trim or soft cut the level is held for 30 polls
//              (~15 min) and the night minimum is suppressed, so it no longer
//              bounces back on the next poll
//          (4) single-phase EV load is on grid L2 in this installation
//              (CFG.EV_1PHASE_GRID_PHASE) — used for headroom, EV load
//              subtraction and labels
//          (5) single-phase EV is only session-cut when the overload is on
//              its own phase — house load on another phase can't be fixed by
//              the EV
// v3.90 - EV v2.19: fixes from full simulation review —
//          (1) battery state machine: amps computed for one direction could be
//              applied in the other during confirmation / forced idle (e.g.
//              discharging at charge amps for a cycle) and the idle step
//              between charge and discharge could be skipped; lastState is now
//              stored after confirmation and after the hard stop
//          (2) EV ramp: counter never reset after a step-up, so after the first
//              15 min the EV climbed 1A per poll; now max +1A per earned
//              window, counter resets on every step-up and does not accumulate
//              while no car is connected
//          (3) single-phase EV load (6A L1) is subtracted from the battery
//              discharge target and added back to L1 headroom
//          (4) headroom add-back only when EV current is actually flowing
//          (5) overload cut logic only runs when a car is connected
//          (6) negative-price minimum charge no longer overrides grid headroom
//          (7) Zaptec finished-early nudge limited to 3 attempts per episode
//              and skipped when ev_soc is unavailable
//          (8) l1HardOverload / l1WarnOverload exposed for the logger
// v3.89 - Bug fixes: evPhaseMode and evCanCharge now always set in all
//          branches of evSafeAmps determination — were undefined in the solar
//          surplus L1 fallback branch; dischargeTargetW corrected when EV not
//          charging (was subtracting 0, now clearly gridImport * 1000)
// v3.88 - Bug fixes: evLastAmps reset on disconnect; removed dead vars
// v3.87 - Cleanup: removed dead code (l1GraduatedCut, sixAmpResolves,
//          overloadTriggered, EV_L1_OVERLOAD_CYCLES, EV_MAX_AMPS,
//          EV_SOLAR_MIN_W, EV_SOLAR_EXIT_W); evJustFinished now has a
//          5-poll cooldown (~2.5 min) before nudging Zaptec again instead
//          of firing every cycle; session cut sends 5A (Zaptec minimum)
//          instead of 0A since Zaptec ignores 0A on the current entity
// v3.86 - EV v2.15: overload response based on current EV amps, not raw phase
//          threshold; phase > 20A with EV at 8A+ → drop to 6A L1 (soft cut);
//          phase > 20A with EV already at 6A → house caused overload → session
//          cut (0A); removes EV_L1_GRADUATED_LIMIT — no longer needed
// v3.85 - EV v2.14: graduated soft cut — phase load 20-22.5A drops to 8A
//          3-phase instead of jumping straight to 6A L1
// v3.84 - EV v2.13: force Zaptec write when connected_finished but evSoC < 100
// v3.83 - EV v2.12: evShouldWrite gated on evCarConnected
// v3.80 - EV v2.9: EV_RAMP_UP_POLLS raised 10 → 30 (~15 min at 30s polls)
// v3.79 - EV v2.8: phase headroom add-back; ramp-down lock
// v3.78 - EV v2.7: night discharge no longer caps EV
// v3.77 - EV v2.6: night discharge cap raised to 8A 3-phase
// v3.76 - Hard stop fix: batterySoC >= 97% forces dc_amps to 0
// v3.75 - (superseded)
// v3.74 - EV v2.5: daytime 3-phase up to 8A when isPriceVeryLow
// v3.73 - EV v2.4: EV_RAMP_UP_POLLS raised 4 → 10
// v3.72 - EV v2.3: daytime 3-phase ramp only at price <= 0
// v3.71 - EV v2.2: raw DSMR phase amps, no add-back
// v3.70 - EV v2.1: session cut only when house load alone >20A
// v3.69 - evCarFull sends 0A
// v3.68 - smarter overload response
// v3.65 - blackout window 17h-19h set to 5A

var EMS_VERSION = 'EMS v3.93';
var EV_VERSION = 'EV v2.22';

var CFG = {
  MAX_AMPS: 100,
  BATTERY_VOLTAGE: 48,
  BATTERY_KWH: 40,
  SOC_MIN: 10,
  SOC_MAX: 95,
  SOC_DISCHARGE_MIN: 15,
  SOC_CRITICAL: 15,
  CHARGE_THRESHOLD: 0.80,
  DISCHARGE_THRESHOLD: 1.20,
  CHARGE_ABS_RATIO: 0.55,
  DISCHARGE_ABS_RATIO: 0.55,
  DISCHARGE_OVERSHOOT: 1.25,
  EXPORT_BIAS_W: 800,
  HYSTERESIS: 0.05,
  SOLAR_SURPLUS_W: 500,
  SOLAR_SURPLUS_EXIT_W: 200,
  ROUND_TRIP_EFF: 0.85,
  GRID_MAX_A_PHASE: 18,
  GRID_VOLTAGE: 230,
  SAFETY_MARGIN_A: 2,
  MIN_DISCHARGE_A: 35,
  MIN_CHARGE_A: 10,
  SOLAR_SUPPRESS_DISCHARGE_W: 500,
  EV_RATE_LIMIT_MS: 15 * 60 * 1000,
  EV_PUBLIC_RATE: 0.50,
  EV_1PHASE_GRID_PHASE: 2      // grid phase the Zaptec uses in single-phase mode (measured: L2)
};

var currentPrice = parseFloat(msg.currentPrice) || 0;
var avgPrice = parseFloat(msg.avgPrice) || 0.10;
var inChargingWindow = msg.inChargingWindow;

var gridImport = parseFloat(msg.gridImport) || 0;
var gridExport = parseFloat(msg.gridExport) || 0;

var zaptecMode = msg.zaptecMode || '';
var lastEvAmps = context.get('evLastAmps') || 0;
var evChargingW = (msg.EVChargeLoad !== undefined && msg.EVChargeLoad !== null)
  ? parseFloat(msg.EVChargeLoad) || 0
  : lastEvAmps * CFG.GRID_VOLTAGE * 3;

var evSoCRaw = parseFloat(msg.ev_soc);
var evSoCKnown = !isNaN(evSoCRaw);
var evSoC = evSoCKnown ? evSoCRaw : 0;
// "Car full" only when the SoC is actually known — unknown SoC (guest car, or car
// integration offline) must never block charging. Informational: stops nudges only.
var evCarFull = (zaptecMode === 'connected_finished') && evSoCKnown && evSoC >= 100;

var evCarConnected = (
  zaptecMode === 'connected_charging' ||
  zaptecMode === 'connected_finished' ||
  zaptecMode === 'connected_requesting' ||
  zaptecMode === 'waiting'
);
var evDrawing = zaptecMode === 'connected_charging' || evChargingW > 0;

var phaseL1kW = parseFloat(msg.phaseL1) || 0;
var phaseL2kW = parseFloat(msg.phaseL2) || 0;
var phaseL3kW = parseFloat(msg.phaseL3) || 0;
var pac1 = parseFloat(msg.pac1) || 0;
var pac2 = parseFloat(msg.pac2) || 0;
var pac3 = parseFloat(msg.pac3) || 0;
var batterySoC = parseFloat(msg.batterySoC) || 50;

var rawNetGridW = (gridImport - gridExport) * 1000 - evChargingW;
var netGridW = Math.max(0, rawNetGridW);

var phaseL1A = (phaseL1kW * 1000) / CFG.GRID_VOLTAGE;
var phaseL2A = (phaseL2kW * 1000) / CFG.GRID_VOLTAGE;
var phaseL3A = (phaseL3kW * 1000) / CFG.GRID_VOLTAGE;
var maxPhaseLoadA = Math.max(phaseL1A, phaseL2A, phaseL3A);
var worstPhaseHeadroomA = Math.max(0, CFG.GRID_MAX_A_PHASE - maxPhaseLoadA - CFG.SAFETY_MARGIN_A);
var gridHeadroomW = worstPhaseHeadroomA * CFG.GRID_VOLTAGE * 3;
var maxChargeFromGridA = Math.round((gridHeadroomW / CFG.BATTERY_VOLTAGE) * CFG.ROUND_TRIP_EFF);
var maxAllowedChargeA = Math.min(CFG.MAX_AMPS, maxChargeFromGridA);

var EV_3PHASE_MIN_A = 7;

// EV draws on all phases in 3-phase mode; in single-phase mode only on the
// charger's single phase (CFG.EV_1PHASE_GRID_PHASE — L2 in this installation)
var evIs3PhB = lastEvAmps >= EV_3PHASE_MIN_A;
var evContribB = function (p) { return (evIs3PhB || p === CFG.EV_1PHASE_GRID_PHASE) ? lastEvAmps : 0; };
var homeL1W = Math.max(0, phaseL1A - evContribB(1)) * CFG.GRID_VOLTAGE;
var homeL2W = Math.max(0, phaseL2A - evContribB(2)) * CFG.GRID_VOLTAGE;
var homeL3W = Math.max(0, phaseL3A - evContribB(3)) * CFG.GRID_VOLTAGE;
var homeImportW = homeL1W + homeL2W + homeL3W;
var dischargeTargetW = evChargingW > 0
  ? Math.max(0, homeImportW)         // EV charging: use house-only import
  : Math.max(0, gridImport * 1000);  // no EV: full grid import is the target

var negPriceHoursRemaining = parseInt(msg.negPriceHoursRemaining) || 1;
var inPreDischargeWindow = msg.inPreDischargeWindow === true;
var inSolarPreDischargeWindow = msg.inSolarPreDischargeWindow === true;
var solarPreDischargeTargetSoC = parseFloat(msg.solarPreDischargeTargetSoC) || 15;
var kwhToFreeForSolar = parseFloat(msg.kwhToFreeForSolar) || 0;
var hoursUntilNegWindow = parseFloat(msg.hoursUntilNegWindow) || 99;
var futureNegHoursCount = parseInt(msg.futureNegHoursCount) || 0;

var lastState = context.get('lastState') || 'idle';
var pendingState = context.get('pendingState') || 'idle';
var pendingCount = context.get('pendingCount') || 0;

var solarTotalW = pac1 + pac2 + pac3;
var actualSurplusW = (rawNetGridW < 0 && solarTotalW > 50)
  ? Math.min(Math.abs(rawNetGridW), solarTotalW) : 0;

var priceRatio = avgPrice > 0 ? currentPrice / avgPrice : 1;
var isNegPrice = currentPrice < 0;

var chargeAbsMax = avgPrice * CFG.CHARGE_ABS_RATIO;
var dischargeAbsMin = avgPrice * CFG.DISCHARGE_ABS_RATIO;

var dischargeRatioThreshold = lastState === 'discharging' ? CFG.DISCHARGE_THRESHOLD - CFG.HYSTERESIS : CFG.DISCHARGE_THRESHOLD;

var isPriceLow;
var isPriceVeryLow = priceRatio <= CFG.CHARGE_THRESHOLD && currentPrice <= chargeAbsMax;

var currentHourInt = new Date().getHours();
var cheapestHourInt = (msg.cheapestHour !== undefined && msg.cheapestHour !== null) ? parseInt(msg.cheapestHour) : -1;
var isCheapestHour = cheapestHourInt >= 0 && currentHourInt === cheapestHourInt && currentPrice <= avgPrice;

var chargeCriticalMax = avgPrice * 0.70;
if (batterySoC <= CFG.SOC_CRITICAL && currentPrice < avgPrice && currentPrice <= chargeCriticalMax) {
  isPriceLow = true;
} else if (inChargingWindow === null) {
  isPriceLow = isPriceVeryLow || isNegPrice;
} else {
  isPriceLow = inChargingWindow || isPriceVeryLow || isNegPrice || isCheapestHour;
}

var isPriceHigh;
if (msg.inDischargeWindow === true) {
  isPriceHigh = currentPrice >= avgPrice && currentPrice >= dischargeAbsMin;
} else {
  isPriceHigh = priceRatio >= dischargeRatioThreshold && currentPrice >= dischargeAbsMin;
}

var canCharge = batterySoC < CFG.SOC_MAX;
var canChargeSolar = batterySoC < CFG.SOC_MAX;
var canDischarge = batterySoC > CFG.SOC_MIN && batterySoC >= CFG.SOC_DISCHARGE_MIN;

var solarSurplusThreshold = lastState === 'charging' ? CFG.SOLAR_SURPLUS_EXIT_W : CFG.SOLAR_SURPLUS_W;
var CONFIRM_CYCLES = (isPriceLow || isPriceHigh || isNegPrice || (actualSurplusW > solarSurplusThreshold && canChargeSolar)) ? 1 : 2;

var charging = false;
var discharging = false;
var targetAmps = 0;
var reason = '';

if (isNegPrice && canCharge) {
  var usableCapacity = CFG.BATTERY_KWH * ((CFG.SOC_MAX - CFG.SOC_MIN) / 100);
  var currentKwh = CFG.BATTERY_KWH * ((batterySoC - CFG.SOC_MIN) / 100);
  var kwhHeadroom = Math.max(0, usableCapacity - currentKwh);
  var targetKwPerHour = kwhHeadroom / negPriceHoursRemaining;
  var spreadAmps = Math.round((targetKwPerHour * 1000) / CFG.BATTERY_VOLTAGE / CFG.ROUND_TRIP_EFF);
  var homeLoadW = solarTotalW + rawNetGridW;
  var solarForBatteryW = Math.max(0, solarTotalW - homeLoadW);
  var solarOffsetAmps = Math.round(solarForBatteryW / CFG.BATTERY_VOLTAGE);
  var gridAmps = Math.max(0, spreadAmps - solarOffsetAmps);
  var negAmps = Math.min(maxAllowedChargeA, Math.max(CFG.MIN_CHARGE_A, spreadAmps));  // grid headroom always wins
  charging = true;
  targetAmps = negAmps;
  reason = 'Negative price (' + currentPrice.toFixed(3) + ' EUR/kWh) - charging at ' + targetAmps + ' A'
    + ' (' + negPriceHoursRemaining + ' neg-price hour(s) remaining,'
    + ' spreading ' + kwhHeadroom.toFixed(1) + ' kWh over window'
    + (solarOffsetAmps > 0 ? ', solar covers ~' + solarOffsetAmps + ' A, grid ~' + gridAmps + ' A' : '') + ')';

} else if (isPriceLow && canCharge) {
  var priceDiscount = 1 - priceRatio;
  var fraction = Math.max(0.10, Math.min(1.0, 0.50 + (priceDiscount * 2.5)));
  charging = true;
  if (batterySoC <= CFG.SOC_CRITICAL) {
    targetAmps = maxAllowedChargeA;
    reason = 'Critical SoC (' + batterySoC + '%) - charging at max ' + targetAmps + ' A (price ' + currentPrice.toFixed(3) + ' EUR below avg ' + avgPrice.toFixed(3) + ' EUR)';
  } else if (inChargingWindow) {
    targetAmps = Math.round(maxAllowedChargeA * fraction);
    reason = 'Planner: cheapest window (' + currentPrice.toFixed(3) + ' EUR) - charging at ' + targetAmps + ' A. Hours: ' + (msg.plannedChargeHours || []).join('h,') + 'h';
  } else {
    targetAmps = Math.round(maxAllowedChargeA * fraction);
    reason = 'Price override: ' + Math.round(priceRatio * 100) + '% of avg (' + currentPrice.toFixed(3) + ' EUR) below threshold - charging at ' + targetAmps + ' A outside planned window';
  }

} else if (actualSurplusW > solarSurplusThreshold && canChargeSolar && !msg.inDischargeWindow) {
  var surplusAmps = Math.round((actualSurplusW / CFG.BATTERY_VOLTAGE) / CFG.ROUND_TRIP_EFF);
  charging = true;
  targetAmps = Math.min(CFG.MAX_AMPS, surplusAmps);
  reason = 'Solar surplus ' + actualSurplusW.toFixed(0) + ' W (' + solarTotalW.toFixed(0) + ' W produced) - absorbing at ' + targetAmps + ' A';

} else if (inSolarPreDischargeWindow && canDischarge && batterySoC > solarPreDischargeTargetSoC) {
  var solarPreAmps = Math.max(CFG.MIN_DISCHARGE_A, Math.min(CFG.MAX_AMPS,
    Math.round((kwhToFreeForSolar * 1000) / CFG.BATTERY_VOLTAGE)
  ));
  discharging = true;
  targetAmps = solarPreAmps;
  reason = 'Solar pre-discharge: solar will fill battery before cheap window'
    + ' - discharging ' + targetAmps + ' A'
    + ' (target SoC ' + solarPreDischargeTargetSoC + '%'
    + ', freeing ' + kwhToFreeForSolar.toFixed(1) + ' kWh for cheap grid charging)';

} else if (inPreDischargeWindow && canDischarge) {
  var preDischargeHoursCount = (msg.preDischargeHours || []).length || 1;
  var currentKwhPD = CFG.BATTERY_KWH * ((batterySoC - CFG.SOC_MIN) / 100);
  var minKwhPD = CFG.BATTERY_KWH * ((CFG.SOC_DISCHARGE_MIN - CFG.SOC_MIN) / 100);
  var kwhToDischarge = Math.max(0, currentKwhPD - minKwhPD);
  var targetKwPD = kwhToDischarge / preDischargeHoursCount;
  var preAmps = Math.round((targetKwPD * 1000) / CFG.BATTERY_VOLTAGE);
  var clampedPreAmps = Math.max(CFG.MIN_DISCHARGE_A, Math.min(CFG.MAX_AMPS, preAmps));
  discharging = true;
  targetAmps = clampedPreAmps;
  reason = 'Pre-discharge: neg price in ' + hoursUntilNegWindow + 'h (' + futureNegHoursCount + ' neg hour(s))'
    + ' - discharging ' + targetAmps + ' A to free ' + kwhToDischarge.toFixed(1) + ' kWh'
    + ' over ' + preDischargeHoursCount + 'h (SoC ' + batterySoC + '% → ' + CFG.SOC_DISCHARGE_MIN + '%)';

} else if (isPriceHigh && canDischarge) {
  if (dischargeTargetW > 0) {
    var evIsCharging = evChargingW > 0 || lastEvAmps > 0;
    var exportBias = (solarTotalW > 500 || evIsCharging) ? 0 : CFG.EXPORT_BIAS_W;
    var targetW = dischargeTargetW + exportBias;
    var neededAmps = Math.round((targetW / CFG.BATTERY_VOLTAGE) * CFG.DISCHARGE_OVERSHOOT);
    var clampedAmps = Math.max(CFG.MIN_DISCHARGE_A, Math.min(CFG.MAX_AMPS, neededAmps));
    discharging = true;
    targetAmps = clampedAmps;
    reason = 'High price (' + (priceRatio * 100).toFixed(0) + '% of avg, ' + currentPrice.toFixed(3) + ' EUR) - discharging ' + targetAmps + ' A to cover ' + dischargeTargetW.toFixed(0) + ' W gross import' + (exportBias > 0 ? ' + ' + exportBias + ' W export bias' : ' (no bias, solar active)') + (neededAmps < CFG.MIN_DISCHARGE_A ? ' (raised to minimum ' + CFG.MIN_DISCHARGE_A + ' A)' : '');
  } else if (actualSurplusW > 0) {
    var importOnlyW = Math.max(0, gridImport * 1000 - evChargingW);
    if (importOnlyW > 0) {
      var throttleAmps = Math.round((importOnlyW / CFG.BATTERY_VOLTAGE) * CFG.DISCHARGE_OVERSHOOT);
      throttleAmps = Math.max(CFG.MIN_DISCHARGE_A, Math.min(CFG.MAX_AMPS, throttleAmps));
      discharging = true;
      targetAmps = throttleAmps;
      reason = 'High price (' + (priceRatio * 100).toFixed(0) + '% of avg, ' + currentPrice.toFixed(3) + ' EUR) - throttled discharge ' + targetAmps + ' A (solar exporting ' + actualSurplusW.toFixed(0) + ' W, covering ' + importOnlyW.toFixed(0) + ' W import only)';
    } else {
      discharging = false;
      targetAmps = 0;
      reason = 'High price (' + (priceRatio * 100).toFixed(0) + '% of avg, ' + currentPrice.toFixed(3) + ' EUR) - solar covers all load (' + actualSurplusW.toFixed(0) + ' W surplus), battery idle';
    }
  } else {
    discharging = true;
    targetAmps = CFG.MIN_DISCHARGE_A;
    reason = 'High price (' + (priceRatio * 100).toFixed(0) + '% of avg, ' + currentPrice.toFixed(3) + ' EUR) - exporting ' + CFG.MIN_DISCHARGE_A + ' A to grid at peak price';
  }

} else {
  reason = 'Idle - SoC ' + batterySoC + '%, price ' + currentPrice.toFixed(3) + ' EUR (' + (priceRatio * 100).toFixed(0) + '% of avg), solar ' + solarTotalW.toFixed(0) + ' W, netGrid ' + netGridW.toFixed(0) + ' W | ' + (msg.plannerReason || 'no planner');
}

if (charging && discharging) { discharging = false; reason += ' [conflict resolved: charge wins]'; }
if (targetAmps === 0) { charging = false; discharging = false; }

// State this cycle's decision branch computed targetAmps for
var decidedState = charging ? 'charging' : discharging ? 'discharging' : 'idle';
var rawState = decidedState;
if (rawState === 'discharging' && lastState === 'charging') { rawState = 'idle'; reason += ' [forced idle: charge → idle → discharge]'; }
if (rawState === 'charging' && lastState === 'discharging') { rawState = 'idle'; reason += ' [forced idle: discharge → idle → charge]'; }

var confirmedState;
if (rawState === pendingState) {
  var newCount = pendingCount + 1;
  context.set('pendingCount', newCount);
  if (newCount >= CONFIRM_CYCLES) {
    confirmedState = rawState;
  } else {
    confirmedState = lastState;
    reason += ' [confirming ' + newCount + '/' + CONFIRM_CYCLES + ']';
  }
} else {
  context.set('pendingState', rawState);
  context.set('pendingCount', 1);
  confirmedState = lastState;
  reason += ' [pending change to ' + rawState + ' 1/' + CONFIRM_CYCLES + ']';
}

// Only apply targetAmps when the confirmed state is the one they were computed
// for. While confirming or during a forced-idle transition, hold idle — never
// apply charge amps as discharge amps or vice versa.
if (confirmedState !== decidedState) { confirmedState = 'idle'; }
charging = confirmedState === 'charging';
discharging = confirmedState === 'discharging';
targetAmps = (charging || discharging) ? targetAmps : 0;
if (targetAmps === 0) { charging = false; discharging = false; }

var dc_amps = charging ? targetAmps : 0;
var dc_power = discharging ? targetAmps * CFG.BATTERY_VOLTAGE : 0;

// ── Hard stop — enforced just before output ───────────────────────────────────
// If SoC >= 97% force dc_amps to 0 regardless of what any branch decided.
if (batterySoC >= 97) {
  dc_amps = 0;
  charging = false;
  reason = 'HARD STOP: SoC ' + batterySoC + '% >= 97% — charging blocked to protect battery';
}

// Persist the state actually sent to the inverter (after confirmation + hard stop)
context.set('lastState', charging ? 'charging' : discharging ? 'discharging' : 'idle');

msg.payload = {
  version: EMS_VERSION + ' / Planner ' + (msg.plannerVersion || 'unknown'),
  dc_amps: dc_amps,
  dc_power: dc_power,
  charging: charging,
  discharging: discharging,
  reason: reason,
  planner: {
    inWindow: msg.inChargingWindow,
    inDischargeWindow: msg.inDischargeWindow,
    dischargeThreshold: msg.dischargeThreshold || null,
    hoursNeeded: msg.hoursNeeded,
    kwhNeeded: msg.kwhNeeded,
    cheapestPrice: msg.cheapestPrice,
    plannedHours: msg.plannedChargeHours,
    plannedDischargeHours: msg.plannedDischargeHours,
    reason: msg.plannerReason
  },
  inputs: {
    currentPrice: currentPrice,
    avgPrice: avgPrice,
    priceRatio: parseFloat((priceRatio * 100).toFixed(1)),
    chargeAbsMax: parseFloat(chargeAbsMax.toFixed(3)),
    dischargeAbsMin: parseFloat(dischargeAbsMin.toFixed(3)),
    lastState: lastState,
    batterySoC: batterySoC,
    solarTotal_W: solarTotalW,
    netGrid_W: netGridW,
    dischargeTarget_W: dischargeTargetW,
    actualSurplus_W: actualSurplusW,
    phaseL1_A: parseFloat(phaseL1A.toFixed(2)),
    phaseL2_A: parseFloat(phaseL2A.toFixed(2)),
    phaseL3_A: parseFloat(phaseL3A.toFixed(2)),
    maxPhaseLoad_A: parseFloat(maxPhaseLoadA.toFixed(2)),
    worstHeadroom_A: parseFloat(worstPhaseHeadroomA.toFixed(2)),
    gridHeadroom_W: parseFloat(gridHeadroomW.toFixed(0)),
    maxAllowedCharge_A: maxAllowedChargeA,
    evCharging_W: evChargingW,
    evLastAmps: lastEvAmps,
    evSensorUsed: (msg.EVChargeLoad !== undefined && msg.EVChargeLoad !== null)
  },
  timestamp: new Date().toISOString()
};

node.status({
  fill: batterySoC >= 97 ? 'yellow' : charging ? 'green' : discharging ? 'red' : 'grey',
  shape: 'dot',
  text: batterySoC >= 97 ? 'HARD STOP SoC:' + batterySoC + '%' : EMS_VERSION + ' ' + (charging ? 'CHG ' : discharging ? 'DCH ' : 'IDLE ') + targetAmps + 'A | SoC:' + batterySoC + '% | ' + currentPrice.toFixed(3) + 'EUR | solar:' + solarTotalW.toFixed(0) + 'W'
});

// ── EV Charge Controller v2.21 ────────────────────────────────────────────────
//
// v2.17–v2.19 changes: see file header. Changes in v2.16 (vs v2.15):
//
// 1. Dead code removed: l1GraduatedCut, sixAmpResolves, overloadTriggered,
//    EV_L1_OVERLOAD_CYCLES, EV_MAX_AMPS, EV_SOLAR_MIN_W, EV_SOLAR_EXIT_W
//
// 2. evJustFinished has a 5-poll cooldown (~2.5 min) before nudging Zaptec
//    again instead of firing every cycle — prevents harassing Zaptec into
//    dropping a legitimately finished session
//
// 3. Session cut sends 5A (Zaptec minimum) instead of 0A — Zaptec ignores
//    0A on the current entity; use the switch node for a true pause

var currentHour = new Date().getHours();
var currentMin = new Date().getMinutes();

// ── Time windows ──────────────────────────────────────────────────────────────
var EV_BLACKOUT_START = 17;
var EV_BLACKOUT_END = 19;
var EV_NIGHT_START = 22;
var EV_NIGHT_START_MIN = 30;
var EV_NIGHT_END = 7;
var evInBlackout = currentHour >= EV_BLACKOUT_START && currentHour < EV_BLACKOUT_END;
var evInNight = (currentHour > EV_NIGHT_START || (currentHour === EV_NIGHT_START && currentMin >= EV_NIGHT_START_MIN))
  || currentHour < EV_NIGHT_END;

// ── EV constants ──────────────────────────────────────────────────────────────
var EV_MIN_AMPS = 6;
var EV_NIGHT_MAX = 12;
var EV_NIGHT_MIN = 8;
var EV_L1_HARD_LIMIT = 20;
var EV_L1_WARN_LIMIT = 18;
var EV_CUT_COOLDOWN_POLLS = 10;
var EV_RAMP_UP_POLLS = 30;   // ~15 min at 30s polls per 1A step
var EV_FINISHED_COOLDOWN = 5;    // polls between Zaptec nudges when connected_finished early
var EV_FINISHED_MAX_NUDGES = 3;   // stop nudging after this — car may have its own charge limit
var EV_OVERLOAD_FAST_A = 22;   // react at once above this (3A below the 25A fuse)
var EV_HOLD_POLLS = 30;   // ~15 min hold after a trim or soft cut
var EV_1PH = CFG.EV_1PHASE_GRID_PHASE;
var EV_1PH_LABEL = 'single-phase-L' + EV_1PH;
var EV_SOC_PRIORITY_ON = 55;   // EV SoC below this → priority charging
var EV_SOC_PRIORITY_OFF = 60;   // priority ends at or above this (hysteresis)
var EV_LOW_SOC_MAX = 12;   // max amps per phase during priority charging

// ── Retrieve EV persistent state ─────────────────────────────────────────────
var evCutCooldown = context.get('evCutCooldown') || 0;
var evRampClearCount = context.get('evRampClearCount') || 0;
var l1OverloadCount = context.get('l1OverloadCount') || 0;
var evFinishedCooldown = context.get('evFinishedCooldown') || 0;

// ── Battery charge hold-down ──────────────────────────────────────────────────
var EV_CHARGE_HOLDDOWN_CYCLES = 4;
var wasCharging = context.get('battWasCharging') || false;
var holdDownCount = context.get('evHoldDownCount') || 0;
if (charging) {
  holdDownCount = 0;
} else if (wasCharging && !charging) {
  holdDownCount = 1;
} else if (holdDownCount > 0 && holdDownCount < EV_CHARGE_HOLDDOWN_CYCLES) {
  holdDownCount++;
} else {
  holdDownCount = 0;
}
context.set('battWasCharging', charging);
context.set('evHoldDownCount', holdDownCount);
var evInHoldDown = holdDownCount > 0;

// ── Phase loads — raw DSMR, no add-back ──────────────────────────────────────
var evCurrentPerPhase = lastEvAmps;
var evIn3Phase = lastEvAmps >= EV_3PHASE_MIN_A;
var phaseL1LoadA = (phaseL1kW * 1000) / CFG.GRID_VOLTAGE;
var phaseL2LoadA = (phaseL2kW * 1000) / CFG.GRID_VOLTAGE;
var phaseL3LoadA = (phaseL3kW * 1000) / CFG.GRID_VOLTAGE;

// ── Overload detection (v2.20) ────────────────────────────────────────────────
// Confirmed overload: any phase > EV_OVERLOAD_FAST_A (22A) at once, or > 20A on
// two consecutive polls. Single marginal spikes between 20 and 22A are ignored.
// Response:
//   EV on 3 phases → trim: lower the amps by the excess (rounded up) and stay on
//                    3 phases — no Zaptec session restart. Only if that would go
//                    below 7A → soft cut to 6A single-phase.
//   EV single-phase (6A or less) → session cut (5A + cooldown), but only when the
//                    overload is on the EV's own phase.
// After a trim or soft cut the level is held for EV_HOLD_POLLS (~15 min).
var maxPhaseLoad = Math.max(phaseL1LoadA, phaseL2LoadA, phaseL3LoadA);
var anyOver20 = maxPhaseLoad > EV_L1_HARD_LIMIT;
var evOverPrev = context.get('evOverPrev') || false;
context.set('evOverPrev', anyOver20);
var overConfirmed = evCarConnected && (maxPhaseLoad > EV_OVERLOAD_FAST_A || (anyOver20 && evOverPrev));
var overExcessA = Math.max(0, maxPhaseLoad - EV_L1_HARD_LIMIT);
var evPhaseLoadA = [phaseL1LoadA, phaseL2LoadA, phaseL3LoadA][EV_1PH - 1];
var trimAmps = lastEvAmps - Math.ceil(overExcessA);
var evTrim = overConfirmed && evIn3Phase && trimAmps >= EV_3PHASE_MIN_A;
var l1SoftCut = overConfirmed && lastEvAmps > EV_MIN_AMPS && !evTrim;
var l1SessionCut = overConfirmed && lastEvAmps <= EV_MIN_AMPS && evPhaseLoadA > EV_L1_HARD_LIMIT;

// Overload hold
var evHoldPolls = context.get('evHoldPolls') || 0;
var evHoldAmps = context.get('evHoldAmps') || 0;
var evHoldMode = context.get('evHoldMode') || '3-phase';
if (!evCarConnected || l1SessionCut) {
  evHoldPolls = 0;
} else if (evTrim) {
  evHoldPolls = EV_HOLD_POLLS; evHoldAmps = trimAmps; evHoldMode = '3-phase';
} else if (l1SoftCut) {
  evHoldPolls = EV_HOLD_POLLS; evHoldAmps = EV_MIN_AMPS; evHoldMode = EV_1PH_LABEL;
} else if (evHoldPolls > 0) {
  evHoldPolls--;
}
context.set('evHoldPolls', evHoldPolls);
context.set('evHoldAmps', evHoldAmps);
context.set('evHoldMode', evHoldMode);
var inEvHold = evHoldPolls > 0 && !evTrim && !l1SoftCut;

// ── EV low-SoC priority (with hysteresis) ────────────────────────────────────
var evLowSoc = context.get('evLowSocActive') || false;
if (!evCarConnected || !evSoCKnown) {
  evLowSoc = false;
} else if (evSoC < EV_SOC_PRIORITY_ON) {
  evLowSoc = true;
} else if (evSoC >= EV_SOC_PRIORITY_OFF) {
  evLowSoc = false;
}
context.set('evLowSocActive', evLowSoc);

var anyWarnOverload = !anyOver20 && (
  phaseL1LoadA > EV_L1_WARN_LIMIT ||
  phaseL2LoadA > EV_L1_WARN_LIMIT ||
  phaseL3LoadA > EV_L1_WARN_LIMIT);
if (anyWarnOverload) { l1OverloadCount++; } else { l1OverloadCount = 0; }
context.set('l1OverloadCount', l1OverloadCount);

// ── Post-cut cooldown and ramp counter update ─────────────────────────────────
var inCutCooldown = evCutCooldown > 0;

if (l1SessionCut) {
  evCutCooldown = EV_CUT_COOLDOWN_POLLS;
  evRampClearCount = 0;
} else if (inCutCooldown) {
  evCutCooldown--;
  evRampClearCount = 0;
} else if (l1SoftCut || evTrim || inEvHold || !evCarConnected) {
  evRampClearCount = 0;   // also during an overload hold and while no car is connected
} else {
  evRampClearCount++;
}
context.set('evCutCooldown', evCutCooldown);
context.set('evRampClearCount', evRampClearCount);

// ── Phase headroom ─────────────────────────────────────────────────────────────
// Add back EV's own per-phase contribution so headroom reflects house load only.
// Only credit EV current that is actually flowing — crediting lastEvAmps while
// the EV is paused/finished overstates headroom and can overload on resume.
var evAddBack = function (p) { return (evDrawing && (evIn3Phase || p === EV_1PH)) ? lastEvAmps : 0; };
var l1HeadroomA = Math.max(0, EV_L1_HARD_LIMIT - phaseL1LoadA + evAddBack(1));
var l2HeadroomA = Math.max(0, EV_L1_HARD_LIMIT - phaseL2LoadA + evAddBack(2));
var l3HeadroomA = Math.max(0, EV_L1_HARD_LIMIT - phaseL3LoadA + evAddBack(3));
var evPhaseHeadroomA = [l1HeadroomA, l2HeadroomA, l3HeadroomA][EV_1PH - 1];
var worst3PhaseA = Math.min(l1HeadroomA, l2HeadroomA, l3HeadroomA);

// ── Phase mode hysteresis ─────────────────────────────────────────────────────
var EV_PHASE_DROP_CYCLES = 3;
var phaseDropCount = context.get('phaseDropCount') || 0;
if (worst3PhaseA < EV_3PHASE_MIN_A) {
  phaseDropCount = Math.min(phaseDropCount + 1, EV_PHASE_DROP_CYCLES + 1);
} else {
  phaseDropCount = 0;
}
context.set('phaseDropCount', phaseDropCount);
var allow3Phase = evInNight
  ? true
  : (worst3PhaseA >= EV_3PHASE_MIN_A) || (phaseDropCount < EV_PHASE_DROP_CYCLES);

// ── Solar surplus for EV ──────────────────────────────────────────────────────
var SOLAR_EV_MARGIN_W = 200;
var gridExportW = Math.max(0, (gridExport - gridImport) * 1000);
var solarSurplusPerPhaseA = Math.floor((gridExportW - SOLAR_EV_MARGIN_W) / CFG.GRID_VOLTAGE / 3);
var solarSurplusL1A = Math.floor((gridExportW - SOLAR_EV_MARGIN_W) / CFG.GRID_VOLTAGE);
var hasSolarSurplus = gridExportW > SOLAR_EV_MARGIN_W;

// ── Determine evSafeAmps and evPhaseMode ─────────────────────────────────────
var evSafeAmps;
var evPhaseMode;
var evCanCharge;

if (l1SessionCut || inCutCooldown) {
  // House load caused overload — set to Zaptec minimum (5A) to keep session alive
  // but signal via switch node to actually pause charging
  evSafeAmps = 5;
  evPhaseMode = EV_1PH_LABEL;
  evCanCharge = false;

} else if (evTrim) {
  // Confirmed overload on 3 phases — trim by the excess, stay on 3 phases
  evSafeAmps = trimAmps;
  evPhaseMode = '3-phase';
  evCanCharge = true;

} else if (l1SoftCut) {
  // Confirmed overload, trimming would go below 7A — drop to 6A single-phase
  evSafeAmps = EV_MIN_AMPS;
  evPhaseMode = EV_1PH_LABEL;
  evCanCharge = true;

} else if (allow3Phase) {
  var maxAllowed;
  if (evInNight) {
    var rampBase = Math.max(EV_MIN_AMPS, lastEvAmps);
    var rampBonus = evRampClearCount >= EV_RAMP_UP_POLLS ? 1 : 0;   // max +1A per earned window
    maxAllowed = Math.min(EV_NIGHT_MAX, rampBase + rampBonus);
  } else if (evLowSoc) {
    // Priority charging: start at 8A 3-phase, +1A per earned ramp window, max 12A
    var rampBase4 = Math.max(EV_NIGHT_MIN, lastEvAmps);
    var rampBonus4 = evRampClearCount >= EV_RAMP_UP_POLLS ? 1 : 0;
    maxAllowed = Math.min(EV_LOW_SOC_MAX, rampBase4 + rampBonus4);
  } else if (charging || evInHoldDown) {
    maxAllowed = EV_MIN_AMPS;
  } else if (!charging && currentPrice <= 0) {
    var rampBase2 = Math.max(EV_MIN_AMPS, lastEvAmps);
    var rampBonus2 = evRampClearCount >= EV_RAMP_UP_POLLS ? 1 : 0;
    maxAllowed = Math.min(EV_NIGHT_MAX, rampBase2 + rampBonus2);
  } else if (!charging && isPriceVeryLow) {
    var rampBase3 = Math.max(EV_MIN_AMPS, lastEvAmps);
    var rampBonus3 = evRampClearCount >= EV_RAMP_UP_POLLS ? 1 : 0;
    maxAllowed = Math.min(8, rampBase3 + rampBonus3);
  } else if (hasSolarSurplus && solarSurplusPerPhaseA >= EV_3PHASE_MIN_A) {
    maxAllowed = Math.min(16, solarSurplusPerPhaseA + evCurrentPerPhase);
  } else {
    maxAllowed = EV_MIN_AMPS;
  }

  var candidate3 = Math.min(maxAllowed, Math.floor(worst3PhaseA));
  // Priority charging moves up from single-phase only with >= 8A headroom on every
  // phase (stays 3-phase down to 7A) — avoids flapping between 1 and 3 phases
  if (evLowSoc && !evInNight && !evIn3Phase && Math.floor(worst3PhaseA) < EV_NIGHT_MIN) {
    candidate3 = 0;
  }
  if (candidate3 >= EV_3PHASE_MIN_A) {
    evSafeAmps = candidate3;
    evPhaseMode = '3-phase';
  } else {
    evSafeAmps = EV_MIN_AMPS;
    evPhaseMode = EV_1PH_LABEL;
  }
  evCanCharge = true;

  if (evInNight && evSafeAmps < EV_NIGHT_MIN) {
    evSafeAmps = EV_NIGHT_MIN;
    evPhaseMode = '3-phase';
  }

} else {
  if (hasSolarSurplus && solarSurplusL1A + evCurrentPerPhase > EV_MIN_AMPS && !evInNight) {
    evSafeAmps = Math.min(EV_3PHASE_MIN_A - 1, solarSurplusL1A + evCurrentPerPhase);
    evSafeAmps = Math.max(EV_MIN_AMPS, evSafeAmps);
    evPhaseMode = EV_1PH_LABEL;  // no 3-phase headroom — solar on the single phase only
    evCanCharge = true;
  } else if (evInNight) {
    evSafeAmps = EV_NIGHT_MIN;
    evPhaseMode = '3-phase';
    evCanCharge = true;
  } else {
    evSafeAmps = EV_MIN_AMPS;
    evPhaseMode = EV_1PH_LABEL;
    evCanCharge = true;
  }
}

// ── Overload hold — cap at the held level, night minimum suppressed ──────────
if (inEvHold && !l1SessionCut && !inCutCooldown) {
  if (evHoldMode === '3-phase') {
    if (evSafeAmps >= evHoldAmps) { evSafeAmps = evHoldAmps; evPhaseMode = '3-phase'; }
  } else {
    evSafeAmps = EV_MIN_AMPS;
    evPhaseMode = EV_1PH_LABEL;
  }
}

// ── Ramp-down lock ────────────────────────────────────────────────────────────
if (evSafeAmps < lastEvAmps) {
  evRampClearCount = 0;
  context.set('evRampClearCount', evRampClearCount);
}

// ── Car connected? ────────────────────────────────────────────────────────────
var evLastWriteTime = context.get('evLastWriteTime') || 0;
var evTimeSince = new Date().getTime() - evLastWriteTime;

// evCarConnected / evDrawing are defined at the top of the script

// ── EV Decision ───────────────────────────────────────────────────────────────
var evTargetAmps = 0;
var evReason = '';

if (!evCarConnected) {
  evTargetAmps = 0;
  evReason = 'Car not connected (' + (zaptecMode || 'unknown') + ')';

} else if (l1SessionCut) {
  evTargetAmps = 5;
  evPhaseMode = EV_1PH_LABEL;
  evCutCooldown = EV_CUT_COOLDOWN_POLLS;
  evRampClearCount = 0;
  context.set('evCutCooldown', evCutCooldown);
  context.set('evRampClearCount', evRampClearCount);
  evReason = 'Phase overload (L' + EV_1PH + ' ' + evPhaseLoadA.toFixed(1)
    + 'A > 20A, confirmed) — EV at ' + lastEvAmps + 'A single-phase — EV to min 5A, cooldown ' + EV_CUT_COOLDOWN_POLLS + ' polls';

} else if (inCutCooldown) {
  evTargetAmps = 5;
  evPhaseMode = EV_1PH_LABEL;
  evReason = 'Post-cut cooldown (' + evCutCooldown + ' polls remaining) — EV at min 5A';

} else if (evTrim) {
  evTargetAmps = trimAmps;
  evPhaseMode = '3-phase';
  evReason = 'Phase overload (' + maxPhaseLoad.toFixed(1) + 'A > 20A, confirmed) — trimmed '
    + lastEvAmps + 'A → ' + trimAmps + 'A, staying on 3 phases, hold ~15 min';

} else if (l1SoftCut) {
  evTargetAmps = EV_MIN_AMPS;
  evPhaseMode = EV_1PH_LABEL;
  evReason = 'Phase overload (' + maxPhaseLoad.toFixed(1)
    + 'A > 20A, confirmed) — EV at ' + lastEvAmps + 'A — dropped to 6A [L' + EV_1PH + '], hold ~15 min';

} else if (evInBlackout) {
  evTargetAmps = 5;
  evPhaseMode = EV_1PH_LABEL;
  evReason = 'Blackout window ' + EV_BLACKOUT_START + 'h-' + EV_BLACKOUT_END + 'h (cooking peak) - 5A session kept alive [L' + EV_1PH + ']';

} else {
  if (discharging && !evInNight && !evLowSoc) {
    evTargetAmps = EV_MIN_AMPS;
    evPhaseMode = EV_1PH_LABEL;
  } else if (charging && evInNight && !evLowSoc) {
    evTargetAmps = Math.min(8, evSafeAmps);
    evPhaseMode = '3-phase';
  } else {
    evTargetAmps = evSafeAmps;
  }

  if (evInNight && evPhaseMode === '3-phase') {
    evReason = 'Night charging (' + currentPrice.toFixed(3) + ' EUR) - ' + evTargetAmps + 'A [3-phase, max ' + EV_NIGHT_MAX + 'A]'
      + ' ramp=' + evRampClearCount + '/' + EV_RAMP_UP_POLLS
      + ' (headroom: L1=' + l1HeadroomA.toFixed(0) + ' L2=' + l2HeadroomA.toFixed(0) + ' L3=' + l3HeadroomA.toFixed(0) + ')';
  } else if (evPhaseMode === '3-phase') {
    evReason = 'Charging ' + evTargetAmps + 'A [3-phase] (headroom: worst=' + Math.floor(worst3PhaseA) + 'A)';
  } else {
    evReason = 'Charging ' + evTargetAmps + 'A [L' + EV_1PH + ' single-phase] (L' + EV_1PH + ' headroom: ' + evPhaseHeadroomA.toFixed(0) + 'A)';
  }

  if (evLowSoc) {
    evReason += ' — EV SoC ' + evSoC + '% (priority below ' + EV_SOC_PRIORITY_ON + '% until '
      + EV_SOC_PRIORITY_OFF + '%), load limits apply';
  } else if (discharging && !evInNight) {
    evReason += ' — battery discharging, capped at 6A baseline';
  } else if (charging && evInNight) {
    evReason += ' — battery charging, night cap 8A 3-phase';
  } else if (inChargingWindow && currentPrice <= chargeAbsMax) {
    evReason += ' — cheap price window (' + currentPrice.toFixed(3) + ' EUR)';
  } else if (isPriceVeryLow) {
    evReason += ' — price override (' + currentPrice.toFixed(3) + ' EUR, ' + Math.round(priceRatio * 100) + '% of avg)';
  } else if (hasSolarSurplus) {
    evReason += ' — solar surplus ' + gridExportW.toFixed(0) + 'W exported (' + currentPrice.toFixed(3) + ' EUR)';
  } else {
    evReason += ' — baseline (' + currentPrice.toFixed(3) + ' EUR)';
  }
  if (inEvHold) {
    evReason += ' [overload hold: ' + evHoldPolls + ' polls left]';
  }
  if (evCarFull) {
    evReason += ' [Zaptec: finished, car full ' + evSoC + '% — current kept available]';
  } else if (zaptecMode === 'connected_finished') {
    evReason += ' [Zaptec: finished, SoC ' + (evSoCKnown ? evSoC + '%' : 'unknown') + ']';
  }
}

// ── Step-up lock ──────────────────────────────────────────────────────────────
// Every 1A increase must be earned with a fresh EV_RAMP_UP_POLLS window (~15 min)
if (evCarConnected && evTargetAmps > lastEvAmps) {
  evRampClearCount = 0;
  context.set('evRampClearCount', evRampClearCount);
}

// ── EV Session accumulator ────────────────────────────────────────────────────
var evLastCycleTime = context.get('evLastCycleTime') || 0;
var evNowMs = new Date().getTime();
var evCycleSeconds = evLastCycleTime > 0 ? (evNowMs - evLastCycleTime) / 1000 : 0;
context.set('evLastCycleTime', evNowMs);

var evWasConnected = context.get('evWasConnected') || false;
if (!evCarConnected && evWasConnected) {
  context.set('evSessionKwh', 0);
  context.set('evSessionCostAct', 0);
  context.set('evSessionCostPub', 0);
  context.set('evCutCooldown', 0);
  context.set('evRampClearCount', 0);
  context.set('evFinishedCooldown', 0);
  context.set('evLastAmps', 0);  // reset so first write on new session always fires
}
context.set('evWasConnected', evCarConnected);

var evSessionKwh = context.get('evSessionKwh') || 0;
var evSessionCostAct = context.get('evSessionCostAct') || 0;
var evSessionCostPub = context.get('evSessionCostPub') || 0;

var evChargingNowW = parseFloat(msg.EVChargeLoad) || 0;
if (evCarConnected && evChargingNowW > 0 && evCycleSeconds > 0 && evCycleSeconds < 300) {
  var evCycleKwh = (evChargingNowW / 1000) * (evCycleSeconds / 3600);
  evSessionKwh += evCycleKwh;
  evSessionCostAct += evCycleKwh * currentPrice;
  evSessionCostPub += evCycleKwh * CFG.EV_PUBLIC_RATE;
  context.set('evSessionKwh', evSessionKwh);
  context.set('evSessionCostAct', evSessionCostAct);
  context.set('evSessionCostPub', evSessionCostPub);
}

var evInstantKw = evChargingNowW / 1000;
var evInstantCostAct = evInstantKw * currentPrice;
var evInstantCostPub = evInstantKw * CFG.EV_PUBLIC_RATE;
var evInstantSaving = evInstantCostPub - evInstantCostAct;
var evSessionSaving = evSessionCostPub - evSessionCostAct;

// ── Rate limit ────────────────────────────────────────────────────────────────
// evJustFinished: Zaptec in connected_finished but car not full.
// Uses a cooldown (EV_FINISHED_COOLDOWN polls) to avoid hammering the API —
// nudges Zaptec every ~2.5 min instead of every 30s.
var evJustFinished = false;
var evFinishedNudges = context.get('evFinishedNudges') || 0;
if (evCarConnected && zaptecMode === 'connected_finished' && !evCarFull) {   // SoC < 100% or unknown
  if (evFinishedNudges < EV_FINISHED_MAX_NUDGES && evFinishedCooldown <= 0) {
    evJustFinished = true;
    evFinishedNudges++;
    evFinishedCooldown = EV_FINISHED_COOLDOWN;
  } else if (evFinishedCooldown > 0) {
    evFinishedCooldown--;
  }
} else {
  evFinishedCooldown = 0;
  evFinishedNudges = 0;   // reset once Zaptec leaves connected_finished
}
context.set('evFinishedCooldown', evFinishedCooldown);
context.set('evFinishedNudges', evFinishedNudges);

var evShouldWrite = (evTargetAmps !== lastEvAmps) || (evTimeSince >= CFG.EV_RATE_LIMIT_MS) || evJustFinished;
var evShouldWriteZaptec = evCarConnected && evShouldWrite;
if (evShouldWrite) {
  context.set('evLastWriteTime', new Date().getTime());
  context.set('evLastAmps', evTargetAmps);
}

// ── Build EV output message ───────────────────────────────────────────────────
var evCharging = evTargetAmps > 0;

var evMsg = {
  payload: {
    version: EV_VERSION,
    targetAmps: parseFloat(evTargetAmps),
    evCharging: evCharging,
    carConnected: evCarConnected,
    reason: evReason,
    shouldWrite: evShouldWriteZaptec,
    inputs: {
      zaptecMode: zaptecMode,
      currentPrice: currentPrice,
      avgPrice: avgPrice,
      surplus_W: actualSurplusW,
      lastEvAmps: lastEvAmps,
      cheapestHour: msg.cheapestHour,
      cheapestPrice: msg.cheapestPrice,
      currentHour: currentHour,
      evInBlackout: evInBlackout,
      evInNight: evInNight,
      evPhaseMode: evPhaseMode,
      evSafeAmps: evSafeAmps,
      evCanCharge: evCanCharge,
      phaseL1LoadA: parseFloat(phaseL1LoadA.toFixed(2)),
      phaseL2LoadA: parseFloat(phaseL2LoadA.toFixed(2)),
      phaseL3LoadA: parseFloat(phaseL3LoadA.toFixed(2)),
      anyOver20: anyOver20,
      l1HardOverload: anyOver20,
      l1WarnOverload: anyWarnOverload,
      evDrawing: evDrawing,
      l1HeadroomA: parseFloat(l1HeadroomA.toFixed(1)),
      l2HeadroomA: parseFloat(l2HeadroomA.toFixed(1)),
      l3HeadroomA: parseFloat(l3HeadroomA.toFixed(1)),
      worst3PhaseA: parseFloat(worst3PhaseA.toFixed(1)),
      l1OverloadCount: l1OverloadCount,
      l1SessionCut: l1SessionCut,
      l1SoftCut: l1SoftCut,
      evTrim: evTrim,
      evLowSoc: evLowSoc,
      evSoC: evSoC,
      overConfirmed: overConfirmed,
      inEvHold: inEvHold,
      evHoldPolls: evHoldPolls,
      inCutCooldown: inCutCooldown,
      evCutCooldown: evCutCooldown,
      evRampClearCount: evRampClearCount,
      evJustFinished: evJustFinished,
      evFinishedCooldown: evFinishedCooldown,
      evFinishedNudges: evFinishedNudges,
      evInHoldDown: evInHoldDown,
      holdDownCount: holdDownCount,
      phaseDropCount: phaseDropCount,
      allow3Phase: allow3Phase,
      gridExportW: parseFloat(gridExportW.toFixed(0)),
      solarSurplusPerPhaseA: solarSurplusPerPhaseA,
      hasSolarSurplus: hasSolarSurplus,
      timeSince_s: Math.round(evTimeSince / 1000)
    },
    session: {
      kwh: parseFloat(evSessionKwh.toFixed(3)),
      costActual: parseFloat(evSessionCostAct.toFixed(4)),
      costPublic: parseFloat(evSessionCostPub.toFixed(4)),
      saving: parseFloat(evSessionSaving.toFixed(4)),
      instantKw: parseFloat(evInstantKw.toFixed(3)),
      instantCostAct: parseFloat(evInstantCostAct.toFixed(4)),
      instantCostPub: parseFloat(evInstantCostPub.toFixed(4)),
      instantSaving: parseFloat(evInstantSaving.toFixed(4))
    }
  },
  evTargetAmps: evTargetAmps,
  evCharging: evCharging,
  evShouldWrite: evShouldWriteZaptec,
  zaptecValue: parseFloat(evTargetAmps),
  evSessionKwh: parseFloat(evSessionKwh.toFixed(3)),
  evSessionCostAct: parseFloat(evSessionCostAct.toFixed(4)),
  evSessionCostPub: parseFloat(evSessionCostPub.toFixed(4)),
  evSessionSaving: parseFloat(evSessionSaving.toFixed(4)),
  evInstantCostAct: parseFloat(evInstantCostAct.toFixed(4)),
  evInstantCostPub: parseFloat(evInstantCostPub.toFixed(4))
};

return [msg, evMsg];

const p = msg.payload;

if (!p || p.dc_amps === undefined) return null;

if (msg.batterySoC >= 97 ) {

    msg.dc_amps = 0;      // amps when charging, 0 when discharging
    msg.charging = false;

}else{

    msg.dc_amps = p.dc_amps;      // amps when charging, 0 when discharging
    msg.charging = p.charging;

}
msg.dc_power = p.dc_power;     // watts when discharging, 0 when charging
msg.discharging = p.discharging;


return msg;

// EMS Combined Logger v1.4
// Changes from v1.3:
//   - Added shouldWrite to EV log output so Zaptec API write activity is visible
// Changes from v1.1:
//   - function declarations replaced with var expressions (Node-RED sandbox fix)
// Changes from v1.0:
//   - Timestamps in CET (UTC+1) / CEST (UTC+2) instead of UTC
//   - Battery deduplication: only logs when state, SoC or amps changes
//   - Daily log rotation uses local date (midnight Amsterdam, not UTC)

var LOGGER_VERSION = 'Logger v1.4';

// ── CET/CEST timestamp ────────────────────────────────────────────────────────
var getLastSunday = function(y, m) {
    // Last Sunday of month m (0-based) at 01:00 UTC
    var d = new Date(Date.UTC(y, m + 1, 0));
    d.setUTCDate(d.getUTCDate() - d.getUTCDay());
    d.setUTCHours(1, 0, 0, 0);
    return d.getTime();
};
var pad = function(n) { return String(n).padStart(2, '0'); };

var now      = new Date();
var utcMs    = now.getTime();
var year     = now.getUTCFullYear();
var dstStart = getLastSunday(year, 2);   // last Sunday March
var dstEnd   = getLastSunday(year, 9);   // last Sunday October
var isDST    = utcMs >= dstStart && utcMs < dstEnd;
var offsetMs = isDST ? 2 * 3600000 : 1 * 3600000;
var local    = new Date(utcMs + offsetMs);

var isoNow = local.getUTCFullYear() + '-'
    + pad(local.getUTCMonth()+1) + '-'
    + pad(local.getUTCDate()) + 'T'
    + pad(local.getUTCHours()) + ':'
    + pad(local.getUTCMinutes()) + ':'
    + pad(local.getUTCSeconds()) + '.'
    + String(local.getUTCMilliseconds()).padStart(3, '0')
    + (isDST ? '+02:00' : '+01:00');

var date = local.getUTCFullYear() + '-'
    + pad(local.getUTCMonth()+1) + '-'
    + pad(local.getUTCDate());

// ── Message handling ──────────────────────────────────────────────────────────
var line = '';

if (msg.payload && msg.payload.dc_amps !== undefined) {
    // ── Battery message (EMS output 1) ────────────────────────────────────────
    var p = msg.payload;
    var i = p.inputs || {};
    var pl = p.planner || {};

    // Deduplication — only log when state, SoC or amps changes
    var battKey = (p.charging ? 'CHG' : p.discharging ? 'DCH' : 'IDLE')
                + '|' + p.dc_amps
                + '|' + i.batterySoC;
    var lastBattKey = context.get('lastBattKey') || '';
    if (battKey === lastBattKey) return null;
    context.set('lastBattKey', battKey);

    var stateAmps = p.charging ? p.dc_amps + 'A' : p.discharging ? (p.dc_power || 0) + 'W' : '0';
    line = '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n'
         + isoNow + ' | ' + p.version + ' | ' + LOGGER_VERSION + '\n'
         + '  STATE:    ' + (p.charging ? 'CHARGING' : p.discharging ? 'DISCHARGING' : 'IDLE')
         + '  ' + stateAmps + '\n'
         + '  REASON:   ' + p.reason + '\n'
         + '  ── Battery ──\n'
         + '  SoC:      ' + i.batterySoC + '%'
         + '  |  Solar: ' + (i.solarTotal_W||0).toFixed(0) + 'W'
         + '  |  netGrid: ' + (i.netGrid_W||0).toFixed(0) + 'W'
         + '  |  discharge target: ' + (i.dischargeTarget_W||0).toFixed(0) + 'W\n'
         + '  Price:    ' + (i.currentPrice||0).toFixed(3) + ' EUR'
         + '  |  avg: ' + (i.avgPrice||0).toFixed(3) + ' EUR'
         + '  |  ratio: ' + (i.priceRatio||0).toFixed(1) + '%'
         + '  |  chargeAbsMax: ' + (i.chargeAbsMax||0).toFixed(3) + ' EUR\n'
         + '  Phases:   L1=' + (i.phaseL1_A||0).toFixed(2) + 'A'
         + '  L2=' + (i.phaseL2_A||0).toFixed(2) + 'A'
         + '  L3=' + (i.phaseL3_A||0).toFixed(2) + 'A'
         + '  |  worstHeadroom: ' + (i.worstHeadroom_A||0).toFixed(2) + 'A'
         + '  |  maxCharge: ' + (i.maxAllowedCharge_A||0) + 'A\n'
         + '  EV load:  ' + (i.evCharging_W||0).toFixed(0) + 'W'
         + '  |  lastEvAmps: ' + (i.evLastAmps||0) + 'A'
         + '  |  sensorUsed: ' + (i.evSensorUsed||false) + '\n'
         + '  ── Planner ──\n'
         + '  inWindow: ' + pl.inWindow
         + '  |  inDischargeWindow: ' + pl.inDischargeWindow
         + '  |  cheapestPrice: ' + (pl.cheapestPrice||'?') + ' EUR\n'
         + '  chargeHours: [' + (pl.plannedHours||[]).join('h, ') + (pl.plannedHours&&pl.plannedHours.length ? 'h' : '') + ']'
         + '  |  dischargeHours: [' + (pl.plannedDischargeHours||[]).join('h, ') + (pl.plannedDischargeHours&&pl.plannedDischargeHours.length ? 'h' : '') + ']\n'
         + '  kwhNeeded: ' + (pl.kwhNeeded||0) + ' kWh'
         + '  |  threshold: ' + (pl.dischargeThreshold||'?') + ' EUR\n';

} else if (msg.payload && msg.payload.targetAmps !== undefined) {
    // ── EV message (EMS output 2) ─────────────────────────────────────────────
    var e = msg.payload;
    var ei = e.inputs || {};

    // Deduplication — only log when state, amps, phase mode or reason changes
    var evKey = (e.evCharging ? 'ON' : 'OFF')
              + '|' + e.targetAmps
              + '|' + (ei.evPhaseMode||'')
              + '|' + e.reason;
    var lastEvKey = context.get('lastEvKey') || '';
    if (evKey === lastEvKey) return null;
    context.set('lastEvKey', evKey);

    line = '── EV ──────────────────────────────────────────────────────────\n'
         + isoNow + ' | ' + e.version + ' | ' + LOGGER_VERSION + '\n'
         + '  STATE:    ' + (e.evCharging ? 'EV ON' : 'EV OFF')
         + '  ' + e.targetAmps + 'A'
         + '  [' + (ei.evPhaseMode||'?') + ']\n'
         + '  REASON:   ' + e.reason + '\n'
         + '  Car:      ' + (e.carConnected ? 'connected' : 'disconnected')
         + '  |  zaptecMode: ' + (ei.zaptecMode||'?') + '\n'
         + '  Phase loads: L1=' + (ei.phaseL1LoadA||0).toFixed(2) + 'A'
         + '  L2=' + (ei.phaseL2LoadA||0).toFixed(2) + 'A'
         + '  L3=' + (ei.phaseL3LoadA||0).toFixed(2) + 'A\n'
         + '  Headroom: L1=' + (ei.l1HeadroomA||0).toFixed(1) + 'A'
         + '  L2=' + (ei.l2HeadroomA||0).toFixed(1) + 'A'
         + '  L3=' + (ei.l3HeadroomA||0).toFixed(1) + 'A'
         + '  |  worst3Phase: ' + (ei.worst3PhaseA||0).toFixed(1) + 'A\n'
         + '  safeAmps: ' + (ei.evSafeAmps||0) + 'A'
         + '  |  canCharge: ' + (ei.evCanCharge||false)
         + '  |  inNight: ' + (ei.evInNight||false)
         + '  |  inBlackout: ' + (ei.evInBlackout||false) + '\n'
         + '  L1 safety: hard=' + (ei.l1HardOverload||false)
         + '  warn=' + (ei.l1WarnOverload||false)
         + '  count=' + (ei.l1OverloadCount||0)
         + '  sessionCut=' + (ei.l1SessionCut||false) + '\n'
         + '  Solar:    export=' + (ei.gridExportW||0) + 'W'
         + '  surplus=' + (ei.hasSolarSurplus||false)
         + '  perPhase=' + (ei.solarSurplusPerPhaseA||0) + 'A\n'
         + '  Price:    ' + (ei.currentPrice||0).toFixed(3) + ' EUR'
         + '  |  hour: ' + (ei.currentHour||0) + 'h'
         + '  |  lastEvAmps: ' + (ei.lastEvAmps||0) + 'A'
         + '  |  shouldWrite: ' + (e.shouldWrite||false) + '\n';

} else {
    return null;
}

msg.payload  = line;
msg.filename = '/media/logs/ems_log_' + date + '.txt';
return msg;
